class Solution {
  paint(A, B, C) {
    let low = Math.max(...C);
    let high = C.reduce((acc, curr) => acc + curr, 0);
    let ans = -1;
    while (low <= high) {
      const mid = Math.floor((low + high) / 2);
      const canPartition = this.canPartition(C, A, mid);
      if (canPartition) {
        ans = mid;
        high = mid - 1;
      } else {
        low = mid + 1;
      }
    }
    return (ans * B) % 10000003;
  }

  canPartition(nums, m, limit) {
    let load = 0,
      count = 1;
    for (let j = 0; j < nums.length; j++) {
      load = load + nums[j];
      if (load > limit) {
        count++;
        load = nums[j];
      }
    }
    if (count <= m) {
      return true;
    }
    return false;
  }
}

